Class Order
  Private Define products As Vector<String>;

  Method Constructor()
    This.products <- vector();
  EndMethod

  Method Agregar(product As String)
    This.products.append(product);
  EndMethod

  Method Receipt() As String
    Return join(This.products, ", ");
  EndMethod

  Method Duplicate() As Order
    Define duplicate As Order <- New Order();
    For Each product In This.products Do
      duplicate.Agregar(product);
    EndFor
    Return duplicate;
  EndMethod
EndClass

Algorithm Orders
  Define firstItem, secondItem, extra As String;
  Read firstItem;
  Read secondItem;
  Read extra;
  Define order As Order <- New Order();
  order.Agregar(firstItem);
  order.Agregar(secondItem);
  Define copyOrder As Order <- order;
  copyOrder.Agregar(extra);
  Write "Original: ", order.Receipt();
  Write "Copy: ", copyOrder.Receipt();
EndAlgorithm

